package com.gregtech.gregtech.client;
import com.gregtech.gregtech.registry.*;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.api.distmarker.Dist;
@EventBusSubscriber(modid = com.gregtech.gregtech.api.mod.GregTechIdentity.MOD_ID,bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)
public final class CraftingTableClientSetup {@SubscribeEvent public static void screens(net.neoforged.neoforge.client.event.RegisterMenuScreensEvent e){e.register(GTMenuTypes.ADVANCED_CRAFTING.get(),com.gregtech.gregtech.client.gui.AdvancedCraftingScreen::new);}@SubscribeEvent public static void blocks(net.neoforged.neoforge.client.event.RegisterColorHandlersEvent.Block e){java.util.stream.Stream.concat(GTCraftingTables.ADVANCED.stream(),GTCraftingTables.CHARGING.stream()).forEach(b->e.register((s,l,p,t)->t==0?b.get().material().getColor():0xFFFFFF,b.get()));}@SubscribeEvent public static void items(net.neoforged.neoforge.client.event.RegisterColorHandlersEvent.Item e){java.util.stream.Stream.concat(GTCraftingTables.ADVANCED.stream(),GTCraftingTables.CHARGING.stream()).forEach(b->e.register(ItemColorARGB.opaque((s,t)->t==0?b.get().material().getColor():0xFFFFFF),b.get().asItem()));}}
